#!/usr/bin/env node
// verify-local.test.mjs — unit tests for verify-local.mjs.
// M1-01 v1.0 cases; v1.2 cases appended by lane M1-04 (proof-bundle
// spec 1.1 emission: kind mapping, CI=1 split, evidence, tree-Sha
// guard, atomic write). No v1.0/v1.1 case was changed.
// Pure-logic tests plus an injected-ls-tree integrity fixture. Fixture
// files are written from in-process generated bytes BEFORE any child
// process is spawned, so the suite stays green under the EPERM
// write-fault episode; a write that still EPERMs skips that one test.
import assert from "node:assert/strict";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { hostname, tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import {
  atomicWriteText, classifyAB, formatProofBundle, gitBlobSha,
  mapCheckKind, missingObjects, overallVerdict, parseArgs, parseLsTree,
  parseTapFailures, toProofChecks, verifyTreeIntegrity,
  VERIFY_LOCAL_VERSION,
} from "./verify-local.mjs";
import { validateBundle } from "./verify-proof.mjs";

test("parseArgs: exactly one of --pr/--sha", () => {
  assert.throws(() => parseArgs([]), /exactly one/);
  assert.throws(() => parseArgs(["--pr", "5", "--sha", "aaa7490"]), /exactly one/);
  assert.equal(parseArgs(["--pr", "5162"]).pr, 5162);
  assert.equal(parseArgs(["--sha", "aaa749065a"]).sha, "aaa749065a");
  assert.throws(() => parseArgs(["--sha", "not-hex!"]), /hex/);
  assert.throws(() => parseArgs(["--pr", "0"]), /positive/);
});

test("parseLsTree + gitBlobSha round-trip the git framing", () => {
  const content = Buffer.from("hello verify-local\n", "utf8");
  const blob = gitBlobSha(content);
  assert.match(blob, /^[0-9a-f]{40}$/);
  // known git blob id for "hello verify-local\n" framing is stable:
  const entries = parseLsTree(`100644 blob ${blob}\ta/b.txt\n120000 blob ${blob}\tlink\n`);
  assert.equal(entries.length, 2);
  assert.equal(entries[0].path, "a/b.txt");
  assert.equal(entries[1].mode, "120000");
});

test("verifyTreeIntegrity: good file passes, zero-filled file is caught", (t) => {
  const dir = join(tmpdir(), `verify-local-test-${process.pid}`);
  try {
    mkdirSync(join(dir, "a"), { recursive: true });
    writeFileSync(join(dir, "a/good.txt"), "hello verify-local\n");
    writeFileSync(join(dir, "a/empty.txt"), "");
  } catch (e) {
    if (e.code === "EPERM") { t.skip("EPERM episode blocks fixture writes"); return; }
    throw e;
  }
  const good = gitBlobSha(Buffer.from("hello verify-local\n", "utf8"));
  const realBlob = gitBlobSha(Buffer.from("real content\n", "utf8"));
  const entries = [
    { mode: "100644", type: "blob", blob: good, path: "a/good.txt" },
    { mode: "100644", type: "blob", blob: realBlob, path: "a/empty.txt" },
    { mode: "100644", type: "blob", blob: realBlob, path: "a/missing.txt" },
  ];
  const r = verifyTreeIntegrity(entries, dir);
  assert.equal(r.ok, false);
  assert.equal(r.files, 3);
  assert.equal(r.zeroFilled, 1);
  assert.equal(r.mismatchCount, 2);
  const okOnly = verifyTreeIntegrity(entries.slice(0, 1), dir);
  assert.equal(okOnly.ok, true);
});

test("parseTapFailures: collects not-ok names, sorted + deduped", () => {
  const tap = [
    "ok 1 - fine",
    "not ok 2 - broken thing",
    "  not ok 3 - sub also broken",
    "not ok 2 - broken thing",
  ].join("\n");
  assert.deepEqual(parseTapFailures(tap), ["broken thing", "sub also broken"]);
  assert.deepEqual(parseTapFailures("ok 1 - all good"), []);
});

test("classifyAB: identical failure at main is ENVIRONMENTAL", () => {
  const head = { exit: 1, names: ["a", "b"] };
  assert.equal(classifyAB(head, { exit: 1, names: ["a", "b"] }), "ENVIRONMENTAL");
  assert.equal(classifyAB(head, { exit: 1, names: ["a"] }), "FAIL");
  assert.equal(classifyAB(head, { exit: 0, names: [] }), "FAIL");
  assert.equal(classifyAB(head, null), "FAIL");
  assert.equal(classifyAB({ exit: 1 }, { exit: 1 }), "ENVIRONMENTAL");
  assert.equal(classifyAB({ exit: 1 }, { exit: 2 }), "FAIL");
});

test("overallVerdict: FAIL dominates, all-environmental is exit 3", () => {
  const c = (verdict) => ({ verdict });
  assert.deepEqual(overallVerdict([c("PASS")]), { overall: "PASS", exitCode: 0 });
  assert.deepEqual(overallVerdict([c("PASS"), c("FAIL")]), { overall: "FAIL", exitCode: 1 });
  assert.deepEqual(
    overallVerdict([c("ENVIRONMENTAL"), c("NOT-APPLICABLE")]),
    { overall: "ENVIRONMENTAL", exitCode: 3 },
  );
  assert.deepEqual(
    overallVerdict([c("ENVIRONMENTAL"), c("PASS")]),
    { overall: "PASS-WITH-ENVIRONMENTAL", exitCode: 0 },
  );
});

// ---- v1.2 (lane M1-04): proof-bundle-spec v1.1 emission ----

const TREE = "4c4944acfd9cd06193bb13a76678a3a40e7763fb";
const COMMIT = "da9414b65f5e38bca95d0d3ace5ce9cbd6be2e58";
const BASE = "aaa749065a6451321a949ddcb923f3174504fe35";
const internal = (kind, verdict = "PASS", detail = "did the thing") =>
  ({ name: `n-${kind}`, kind, verdict, wallMs: 7, detail });

test("mapCheckKind: internal kinds map to spec 1.1 kinds; check/unknown do not map singly", () => {
  assert.equal(mapCheckKind("materialisation"), "materialisation");
  assert.equal(mapCheckKind("selection"), "selection");
  assert.equal(mapCheckKind("test"), "test");
  assert.equal(mapCheckKind("test-summary"), "test");
  assert.equal(mapCheckKind("preflight"), "preflight");
  assert.equal(mapCheckKind("sweep"), "sweep");
  assert.equal(mapCheckKind("check"), null); // expands to a pair instead
  assert.equal(mapCheckKind("nonsense"), null);
});

test("toProofChecks: detail becomes evidence; check-ci1 expands into the §3.1 pair", () => {
  const out = toProofChecks([
    { name: "materialise", kind: "materialisation", verdict: "ENVIRONMENTAL", wallMs: 5, detail: "3875/3876 blobs mismatch" },
    { name: "check-ci1", kind: "check", verdict: "PASS", wallMs: 9, detail: "CI=1 exit 0" },
    { name: "affected-tests", kind: "test-summary", verdict: "PASS", wallMs: 3, detail: "6 file(s): 6 pass" },
  ]);
  assert.equal(out.length, 4);
  assert.deepEqual(out[0], { name: "materialise", kind: "materialisation", verdict: "ENVIRONMENTAL", wallMs: 5, evidence: "3875/3876 blobs mismatch" });
  assert.equal(out[1].name, "check-ci1:secret-scan");
  assert.equal(out[1].kind, "secret-scan");
  assert.equal(out[2].name, "check-ci1:generation");
  assert.equal(out[2].kind, "generation");
  assert.equal(out[1].verdict, "PASS");
  assert.equal(out[1].wallMs, 9);
  assert.match(out[1].evidence, /CI=1 exit 0/);
  assert.match(out[1].evidence, /not stage-separable/);
  assert.equal(out[3].kind, "test");
  assert.throws(() => toProofChecks([internal("nonsense")]), /no proof-bundle-spec/);
});

test("toProofChecks: empty detail still yields non-empty evidence", () => {
  const out = toProofChecks([{ name: "x", kind: "sweep", verdict: "PASS", wallMs: 0, detail: "" }]);
  assert.ok(out[0].evidence.length > 0);
});

test("formatProofBundle: emits a bundle verify-proof v1.1 validates clean", () => {
  const bundle = formatProofBundle({
    treeSha: TREE, commitSha: COMMIT, pr: 3663, baseSha: BASE, mainSha: BASE,
    startedAt: "2026-10-29T01:55:22.744Z", finishedAt: "2026-10-29T01:55:37.864Z",
    wallMs: 15120, host: hostname(), overall: "ENVIRONMENTAL", exitCode: 3,
    checks: [
      { name: "materialise", kind: "materialisation", verdict: "ENVIRONMENTAL", wallMs: 5073, detail: "3875/3876 blobs mismatch (3876 zero-filled)" },
      { name: "affected-selection", kind: "selection", verdict: "NOT-APPLICABLE", wallMs: 0, detail: "blocked: tree materialisation did not verify" },
      { name: "check-ci1", kind: "check", verdict: "NOT-APPLICABLE", wallMs: 0, detail: "blocked: tree materialisation did not verify" },
      { name: "registration-sweep", kind: "sweep", verdict: "NOT-APPLICABLE", wallMs: 0, detail: "blocked: tree materialisation did not verify" },
    ],
  });
  assert.equal(bundle.bundleVersion, "1.1");
  assert.deepEqual(bundle.producedBy, { tool: "verify-local.mjs", toolVersion: "1.3", host: hostname() });
  assert.equal(bundle.treeSha, TREE);
  assert.equal(bundle.checks.length, 5); // check-ci1 -> pair
  assert.deepEqual(validateBundle(bundle), []);
});

test("formatProofBundle: refuses commit-as-tree and non-Sha tree values", () => {
  const args = {
    commitSha: COMMIT, pr: 3663, baseSha: BASE,
    startedAt: "2026-10-29T00:00:00Z", finishedAt: "2026-10-29T00:01:00Z",
    host: "h", overall: "PASS", exitCode: 0,
    checks: [internal("sweep")],
  };
  assert.throws(() => formatProofBundle({ ...args, treeSha: COMMIT }), /treeSha === commitSha/);
  assert.throws(() => formatProofBundle({ ...args, treeSha: "abc" }), /40-char/);
});

test("formatProofBundle: sha-targeted bundle omits pr and still validates (spec 1.1)", () => {
  const bundle = formatProofBundle({
    treeSha: TREE, commitSha: COMMIT, pr: null, baseSha: BASE,
    startedAt: "2026-10-29T00:00:00Z", finishedAt: "2026-10-29T00:01:00Z",
    host: "h", overall: "PASS", exitCode: 0, checks: [internal("sweep")],
  });
  assert.equal("pr" in bundle, false);
  assert.deepEqual(validateBundle(bundle), []);
});

// ---- v1.3 (POST-EPISODE DISCHARGE re-run): bootstrap on ANY missing
// required object — the PR #4900 defect: head+base present, main absent
// passed the v1.2 head-only probe and the run died at listTree(mainSha).
test("missingObjects: main-only absence is detected (the v1.3 defect case)", () => {
  const HEAD = "a".repeat(40), BASE = "b".repeat(40), MAIN = "c".repeat(40);
  const has = (sha) => sha !== MAIN;
  assert.deepEqual(missingObjects([HEAD, BASE, MAIN], "/anywhere", has), [MAIN]);
});

test("missingObjects: none missing -> empty; all missing -> all, deduped, nulls dropped", () => {
  const HEAD = "a".repeat(40), BASE = "b".repeat(40);
  assert.deepEqual(missingObjects([HEAD, BASE], "/anywhere", () => true), []);
  assert.deepEqual(missingObjects([HEAD, HEAD, BASE, null], "/anywhere", () => false), [HEAD, BASE]);
  assert.deepEqual(missingObjects([], "/anywhere", () => false), []);
});

test("VERIFY_LOCAL_VERSION is 1.3 (bootstrap broadening)", () => {
  assert.equal(VERIFY_LOCAL_VERSION, "1.3");
});

test("atomicWriteText: writes byte-exact content (inlined pattern, no atomic-write import)", (t) => {
  const p = join(tmpdir(), `verify-local-atomic-${process.pid}.json`);
  try {
    atomicWriteText(p, "{\"ok\":true}\n");
  } catch (e) {
    if (e.code === "EPERM") { t.skip("EPERM episode blocks the write in this seat"); return; }
    throw e;
  }
  assert.equal(readFileSync(p, "utf8"), "{\"ok\":true}\n");
});
